materialContextUI=createMaterialContext({getChoices:()=>materialsUI.snapshot(),onEngage:()=>{if(playback)stopPlayback('reading');},onView:category=>{if(!house)return;choose({wall:'wall-section',roof:'roof',facade:'facade'}[category]);},onChoose:category=>{if(!house)return;({wall:openWallMaterials,roof:openRoofMaterials,facade:openFacadeMaterials})[category]();},onCompare:category=>{if(house)openMaterials(category);},onBrief:()=>{if(house)openProjectBrief();}});
projectDiscussionUI=createProjectDiscussion({store:materialsUI,context:projectContext,getStyle:()=>currentStyle});window.__discussionQA=()=>projectDiscussionUI.audit();
const familyPlanUI=createFamilyPlan({context:projectContext,onBrief:openProjectBrief,onEnter:async id=>{await start();if(!house)return false;choose('plan');roomExplorer.select(id);enterRoom(id);return active==='walk'&&window.__HOUSE_STATUS__.walk?.room===id;}});window.__familyPlanQA=()=>familyPlanUI.audit();
publicSite=createPublicSite({store:materialsUI,context:projectContext,onChoose:openProjectStep,onBrief:openProjectBrief,getStyle:()=>currentStyle,onExplore:async kind=>{await start();if(!house)return false;if(kind==='build')showConstruction(true);else choose(kind);return true;}});


function updateLightingUI(state){$('#lighting-current').textContent=state.title;$('#lighting-description').textContent=state.preset==='evening'?'Более спокойный свет снаружи и тёплые светильники внутри.':'Мягкий свет у окон и светлое дневное небо.';document.querySelectorAll('[data-lighting]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lighting===state.preset)));}
function setLighting(id){if(!lighting||!Object.hasOwn(lightPresets,id))return;if(story?.active)choose('assembled');if(studyView?.active||roofStudyView?.active){wallInspector.close({restoreFocus:false});roofInspector.close({restoreFocus:false});}currentLighting=id;lighting.select(id,{reduced:matchMedia(reduced.media).matches});}
document.querySelectorAll('[data-lighting]').forEach(b=>b.addEventListener('click',()=>setLighting(b.dataset.lighting)));

function enterRoom(id){if(!house||!walkUI||!['plan','cutaway'].includes(active)||id&&!navigation.rooms.some(r=>r.id===id))return;if(['plan','cutaway'].includes(active))roomReturn={mode:active,position:camera.position.clone(),target:controls.target.clone(),fov:camera.fov,zoom:camera.zoom,min:controls.minDistance,max:controls.maxDistance,aspect:camera.aspect};const damping=controls.enableDamping;controls.enableDamping=false;controls.update();controls.enableDamping=damping;choose('walk',{room:id,keepRoomReturn:true});$('#canvas').scrollIntoView({block:'start',behavior:'instant'});renderer.domElement.focus({preventScroll:true});}
function returnToRooms(){if(!house||active!=='walk')return;const saved=roomReturn;choose(saved?.mode||'plan',{keepRoomReturn:true});if(saved){cameraGoal=targetGoal=null;camera.position.copy(saved.position);controls.target.copy(saved.target);camera.fov=saved.fov;controls.minDistance=saved.min;controls.maxDistance=saved.max;if(Math.abs(camera.aspect-saved.aspect)<1e-6)camera.zoom=saved.zoom;const damping=controls.enableDamping;controls.enableDamping=false;controls.update();controls.enableDamping=damping;camera.updateProjectionMatrix();}roomReturn=null;roomExplorer?.invalidate();dirty=true;$('#canvas').scrollIntoView({block:'start',behavior:'instant'});roomExplorer?.update();const id=window.__HOUSE_STATUS__.walk?.room||'living',marker=document.querySelector('[data-room-marker="'+id+'"]:not([hidden])'),fallback=document.querySelector('[data-room-select="'+id+'"]');(marker||fallback).focus({preventScroll:true});if(!marker)fallback.scrollIntoView({block:'nearest',behavior:'instant'});}
$('#walk-plan').addEventListener('click',returnToRooms);
createProjectDraft({context:projectContext,store:materialsUI,getStyle:()=>currentStyle,setStyle:id=>{if(styles)setInteriorStyle(id);else currentStyle=id;}});
createProjectTransfer({context:projectContext,store:materialsUI,getStyle:()=>currentStyle,setStyle:id=>{if(styles)setInteriorStyle(id);else currentStyle=id;}});
createCompanyContact({store:materialsUI,context:projectContext});
if(innerWidth>900)start();
